import hashlib

records = ["Ali ne Sara ko 500 diye", "Sara ne Hamza ko 200 diye", "Hamza ne Ali ko 100 diye"]
tamper_block = 1        # kaun sa block badla jaye (0, 1, 2) ya None

def make_hash(data, prev_hash):
    return hashlib.sha256((data + prev_hash).encode()).hexdigest()[:10]

chain = []
prev = "0000000000"
for data in records:
    h = make_hash(data, prev)
    chain.append([data, prev, h])
    prev = h

for i, block in enumerate(chain):
    print("Block", i, "| hash:", block[2], "| pichhla:", block[1])

if tamper_block is not None:
    chain[tamper_block][0] = "Sara ne Hamza ko 9000 diye"

ok = True
for i, (data, prev_hash, saved) in enumerate(chain):
    if make_hash(data, prev_hash) != saved:
        print("Block", i, "badla gaya hai! Chain toot gayi.")
        ok = False
if ok:
    print("Chain theek hai: koi record nahi badla.")
